#include <vector>
#include <algorithm>
using namespace std;

class Solution {
public:
    long long maximizeExpression(vector<int>& nums) {
        long long max_i = -4e18;
        long long max_ij = -4e18;
        long long max_ijk = -4e18;
        for (int x : nums) {
            if (max_ij > -3e18) max_ijk = max(max_ijk, max_ij + x);
            if (max_i > -3e18) max_ij = max(max_ij, max_i - x);
            max_i = max(max_i, (long long)x);
        }
        return max_ijk;
    }
};

class Solution {
    public long maximizeExpression(int[] nums) {
        long maxI = Long.MIN_VALUE / 2;
        long maxIJ = Long.MIN_VALUE / 2;
        long maxIJK = Long.MIN_VALUE / 2;
        for (int x : nums) {
            maxIJK = Math.max(maxIJK, maxIJ + x);
            maxIJ = Math.max(maxIJ, maxI - x);
            maxI = Math.max(maxI, (long)x);
        }
        return maxIJK;
    }
}

var maximizeExpression = function(nums) {
    let maxI = null;
    let maxIJ = null;
    let maxIJK = null;
    for (const val of nums) {
        const x = BigInt(val);
        if (maxIJ !== null) {
            const cand = maxIJ + x;
            if (maxIJK === null || cand > maxIJK) maxIJK = cand;
        }
        if (maxI !== null) {
            const cand = maxI - x;
            if (maxIJ === null || cand > maxIJ) maxIJ = cand;
        }
        if (maxI === null || x > maxI) maxI = x;
    }
    return Number(maxIJK);
};
